typedef struct {
    int id;
    float value;
} ValueStruct; // The alias name

// Usage examples
ValueStruct item;

ValueStruct list_head = {
    .id = 10,
    .value = 99.9f
};

// Typedef for self-referential structures (Linked Lists)
typedef struct Node_s {
    int data;
    struct Node_s* next;
} Node; // The alias Node

Node n1;
Node* ptr_n1 = &n1;
Node n2 = {20, NULL};
